      "rollback": {
        "trigger": "integration fails",
        "action": "remove Cosign integration",
        "safety_guard": "verify that images are not signed"
      },
      "verification": {
        "what": "integration status",
        "how": "check logs",
        "expected": "integration successful"
      }
    },
    {
      "id": "generate_sbom",
      "description": "Generate SBOM with Syft for every build",
      "action": "generate",
      "target": "SBOM",
      "risk_class": "medium",
      "preconditions": [
        {
          "description": "Syft is installed",
          "fact": "syft_installed",
          "established_by": "integrate_cosign"
        }
      ]
    },
    {
      "id": "store_signatures",
      "description": "Store signatures in Rekor transparency log",
      "action": "store",
