        "what": "key rotation status",
        "how": "check key validity",
        "expected": "keys successfully rotated"
      }
    }
  ],
  "dependencies": [
    {
      "from_task": "integrate_cosign",
      "to_task": "generate_sbom",
      "kind": "hard"
    },
    {
      "from_task": "integrate_cosign",
      "to_task": "store_signatures",
      "kind": "hard"
    },
    {
      "from_task": "store_signatures",
      "to_task": "verify_images",
      "kind": "hard"
    },
    {
      "from_task": "generate_sbom",
      "to_task": "configure_kyverno",
      "kind": "hard"
    },
    {
      "from_task": "configure_kyverno",
      "to_task": "verify_images",
      "kind": "hard"
    },
    {
      "from_task": "verify_images",
      "to_task": "key_rotation_procedure",
      "kind": "hard"
    }
  ]
}
